 567 std::vector<int> values;
 568 for (size_t i = 0; i < capacity; ++i) {
 569 if (hashTable[i].exists && hashTable[i].key >= lowerBound && hashTable[i].key <= upperBound) {
 570 values.push_back(hashTable[i].value);
 571 }
 572 }
 573 return values;
 574 }
```

