 currentSlotIndex++;
 return; // Tuple loaded successfully
 }
 currentSlotIndex++;
 }

 // Move to the next page
 currentPageIndex++;
 currentSlotIndex = 0;
 }

 // No more tuples available
 currentTuple.reset();
}
```

